toad_implementation.code_blueprint:
canvas {
  size: 880px 340px;
  fill: #E5E7EB;
  font-family: "JetBrains Mono, monospace";
}

>ticketBg = #FFFFFF;
>secBlue = #1E3A8A;
>holoGreen = #10B981;
>lineColor = #9CA3AF;

rect #ticketBody {
  at: center of canvas;
  size: 800px 260px;
  fill: >ticketBg;
  stroke: >lineColor;
  stroke-width: 1px;
  radius: 8px;
}

rect #holoFoil {
  at: top left of #ticketBody offset 24px 24px;
  size: 60px 40px;
  fill: alpha(>holoGreen, 0.25);
  stroke: >holoGreen;
  stroke-width: 1px;
  radius: 4px;
}

text #holoLabel {
  at: center of #holoFoil;
  content: "SECURE";
  font-size: 9px;
  font-weight: 700;
  color: >holoGreen;
}

text #eventTitle {
  at: below #holoFoil offset 20px;
  content: "RADIOHEAD // WORLD TOUR";
  font-size: 22px;
  font-weight: 800;
  color: >secBlue;
}

text #eventDetails {
  at: below #eventTitle offset 8px;
  content: "OLYMPIASTADION BERLIN • 18. JULI 2026 • 20:00";
  font-size: 12px;
  color: #374151;
}

text #seatingInfo {
  at: below #eventDetails offset 20px;
  content: "BLOCK: A3  •  REIHE: 12  •  PLATZ: 44  •  € 115.00";
  font-size: 13px;
  font-weight: 700;
  color: >secBlue;
}

rect #perforationLine {
  at: right of #ticketBody offset -200px 0px;
  size: 2px 260px;
  fill: >lineColor;
}

text #stubTitle {
  at: right of #perforationLine offset 24px -60px;
  content: "STUB / EINLASS";
  font-size: 11px;
  font-weight: 700;
  color: >secBlue;
}

text #stubSeat {
  at: below #stubTitle offset 10px;
  content: "A3 / R12 / P44";
  font-size: 12px;
  font-weight: 700;
  color: #111827;
}

text #barcodeStub {
  at: below #stubSeat offset 24px;
  content: "|||||| |||| |||||||";
  font-size: 20px;
  color: #111827;
}
